<div class="globe-scene" data-globe>
    <button class="scene-activate" type="button" data-scene-activate hidden>Explore in 3D</button>
    <div class="globe-grid" aria-hidden="true"></div><div class="globe-orbit orbit-one" aria-hidden="true"></div><div class="globe-orbit orbit-two" aria-hidden="true"></div>
    <svg class="globe-poster" viewBox="0 0 600 600" aria-hidden="true"><defs><linearGradient id="ribbon-color" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#76e1f6"/><stop offset=".32" stop-color="#159acb"/><stop offset=".65" stop-color="#1456cf"/><stop offset="1" stop-color="#082a85"/></linearGradient><clipPath id="sphere-cut"><circle cx="300" cy="290" r="185"/></clipPath></defs><g transform="rotate(-28 300 290)" clip-path="url(#sphere-cut)" fill="none" stroke="url(#ribbon-color)" stroke-width="38"><ellipse cx="300" cy="150" rx="155" ry="60"/><ellipse cx="300" cy="220" rx="195" ry="80"/><ellipse cx="300" cy="300" rx="205" ry="85"/><ellipse cx="300" cy="380" rx="185" ry="70"/><ellipse cx="300" cy="450" rx="150" ry="60"/></g></svg>
